function crEditCashier(id=''){const c=id?cashState.cashiers.find(x=>x.id===id):{name:'',personnelId:'',status:'فعال',notes:''};const people=crArr(typeof state!=='undefined'?state.personnel:[]).map(p=>({value:p.id,label:`${p.id} | ${p.name}`}));openForm(id?'ویرایش صندوقدار':'افزودن صندوقدار',[{name:'name',label:'نام صندوقدار'},{name:'personnelId',label:'اتصال به پرونده پرسنلی',type:'select',options:people},{name:'status',label:'وضعیت',type:'select',options:['فعال','غیرفعال']},{name:'notes',label:'توضیحات',type:'textarea',full:true}],c,async o=>{if(!crText(o.name))throw Error('نام صندوقدار الزامی است');if(cashState.cashiers.some(x=>x.id!==id&&x.name===crText(o.name)))throw Error('این صندوقدار قبلاً ثبت شده است');if(id)Object.assign(c,o);else cashState.cashiers.push({id:crUid('CASHIER',cashState.cashiers),...o});if(await crCommit(id?'ویرایش صندوقدار':'افزودن صندوقدار')){closeModal();renderView()}})}
function crDeleteCashier(id){const c=crCashier(id);if(!c)return;if(cashState.reports.some(r=>r.cashierId===id))return toast('این صندوقدار گزارش ثبت‌شده دارد و قابل حذف نیست؛ آن را غیرفعال کنید',true);crConfirm('حذف صندوقدار',`صندوقدار «${c.name}» حذف شود؟`,async()=>{cashState.cashiers=cashState.cashiers.filter(x=>x.id!==id);await crCommit('حذف صندوقدار');renderView()})}

