  crCustody.error='';
  const task=(async()=>{try{
    const [cash,reports,entries]=await Promise.all([RAYO_API_GATEWAY.loadModule('cashreport'),crQueryAll('cashreport','reports'),crQueryAll('finance','entries')]);
    crCustody.cash=cash;crCustody.reports=reports.items;crCustody.entries=entries.items;crCustody.financeVersion=entries.version;crCustody.loaded=true;
    cashState.transferAccounts=crArr(cash.transferAccounts);cashState.cashRecipients=crArr(cash.cashRecipients);
  }catch(e){crCustody.loaded=false;crCustody.error=e.message||'دریافت گردش وجوه انجام نشد';throw e}finally{crCustody.loading=false}})();
